"""Build the reviewed first eight daily quiz files. Run from any directory."""
import json
from pathlib import Path
from export_quizduel import build_exports

ROOT = Path(__file__).resolve().parent

# Each item is: verse reference, explanation, then Kid / High School / Expert.
# A question row has a focused stem, the best answer, and three nearby distractors.
BANK = {}

def day(date, rows):
    assert len(rows) == 10, (date, len(rows))
    BANK[date] = rows

