def build():
    for date, rows in BANK.items():
        levels = {key: [] for key in ('kid', 'high-school', 'expert')}
        for number, (reference, explanation, *versions) in enumerate(rows, 1):
            for offset, (level, version) in enumerate(zip(levels, versions)):
                parts = version.split('|')
                assert len(parts) == 5, (date, number, level)
                shift = (number + offset) % 4
                choices = parts[2:]
                choices.insert(shift, parts[1])
                options = [{'id': chr(97 + i), 'text': value} for i, value in enumerate(choices)]
                chapter, verse = reference.split(':', 1)
                start = verse.split('-')[0]
                url = f'https://www.churchofjesuschrist.org/study/scriptures/ot/isa/{chapter}.{start}?lang=eng'
                levels[level].append({
                    'id': f'{date}-{level}-{number:02d}', 'date': date, 'difficulty': level,
                    'question': parts[0], 'options': options,
                    'correctOptionId': chr(97 + shift), 'explanation': explanation,
                    'source': {'reference': f'Isaiah {reference}', 'url': url},
                })
        doc = {'date': date, 'levels': levels}
        doc['quizDuel'] = build_exports(doc)
        (ROOT / f'{date}.json').write_text(json.dumps(doc, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

if __name__ == '__main__':
    build()
